using System.Text.Json;
public class Input {public long[][] bid {get;set;}=Array.Empty<long[]>();public long[][] ask {get;set;}=Array.Empty<long[]>();public long t {get;set;}public long ttl {get;set;}=300000;public long? skew {get;set;} public double[]? rangeClose {get;set;} public double priorHigh {get;set;} public double priorLow {get;set;} }
public static class Kernel{
 static (long,long,string) Last(long[][] a,long t,long ttl){var v=a.Where(r=>r[0]<=t).ToArray();if(v.Length==0)return(0,0,"NO_CAUSAL_SEED");long tm=v.Max(r=>r[0]);var pp=v.Where(r=>r[0]==tm).Select(r=>r[1]).Distinct().ToArray();if(pp.Length!=1)return(0,0,"SAME_MS_CONFLICT");if(t-tm>ttl)return(0,0,"STATE_EXPIRED");return(tm,pp[0],"");}
 public static Dictionary<string,object> State(Input x){var b=Last(x.bid,x.t,x.ttl);var a=Last(x.ask,x.t,x.ttl);string err=b.Item3!=""?b.Item3:a.Item3;if(err==""&&(b.Item2<=0||a.Item2<b.Item2))err="CROSSED_OR_INVALID";if(err==""&&x.skew.HasValue&&Math.Abs(b.Item1-a.Item1)>x.skew.Value)err="SIDE_SKEW";if(err!="")return new(){{"valid",false},{"state",err}};return new(){{"valid",true},{"state","CAUSAL_L1_STATE_REFERENCE_NOT_FILL"},{"bid",b.Item2/100000.0},{"ask",a.Item2/100000.0},{"mid",(b.Item2+a.Item2)/200000.0},{"bid_time_ms",b.Item1},{"ask_time_ms",a.Item1},{"age_ms",Math.Max(x.t-b.Item1,x.t-a.Item1)},{"side_skew_ms",Math.Abs(a.Item1-b.Item1)},{"expiry_ms",x.ttl}};}
 public static int RangeAcceptance(double[] closes,double high,double low)=>closes.All(v=>v>high)?1:closes.All(v=>v<low)?-1:0;
}
public class Program{public static void Main(string[] args){using var o=new StreamWriter(args[1]);foreach(var s in File.ReadLines(args[0])){var x=JsonSerializer.Deserialize<Input>(s)!;var result=Kernel.State(x);if(x.rangeClose!=null)result["range_side"]=Kernel.RangeAcceptance(x.rangeClose,x.priorHigh,x.priorLow);o.WriteLine(JsonSerializer.Serialize(result));}}}
